{"path": "task.py", "content": "def stack_machine(instructions):
    stack = []
    for instr in instructions:
        if isinstance(instr, tuple):
            op = instr[0]
            if op == 'push':
                _, value = instr
                stack.append(value)
            elif op == 'add':
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif op == 'multiply':
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif op == 'negate':
                a = stack.pop()
                stack.append(-a)
            else:
                raise ValueError(f"Unknown instruction {op}")
        else:
            raise ValueError("Instruction must be a tuple")
    if len(stack) != 1:
        raise RuntimeError("Stack must contain exactly one value")
    return stack[0]
